// ***************
// Filename: py_sysctl_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of py_sysctl: joins the register map
//   py_sysctl_regs (modport regs) and the logic py_sysctl (modport core).
//   cfg_* go from the register map to the logic (register values, _wr write
//   pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   py_sysctl_regs.json: edit the JSON and regenerate.
// Date: 2026-10-20
interface py_sysctl_regs_if #(
  parameter int NCLK = 1
) ();
  logic [2-1:0] sts_reset_cause;
  logic [2-1:0] cfg_reset_cause;
  logic cfg_reset_cause_wr;
  logic [32-1:0] sts_boot_status;
  logic [32-1:0] sts_cycles;
  logic [32-1:0] sts_soc_id;
  logic cfg_core_reset;
  logic cfg_core_reset_wr;
  logic [NCLK-1:0] cfg_clk_en;
  logic cfg_clk_en_wr;
  logic [2-1:0] sts_clk_status;
  logic [32-1:0] cfg_timer_cmp;
  logic cfg_timer_cmp_wr;
  logic cfg_timer_ctrl;
  logic cfg_timer_ctrl_wr;
  logic sts_timer_status;
  logic cfg_timer_status;
  logic cfg_timer_status_wr;

  modport regs (output cfg_reset_cause, cfg_reset_cause_wr, cfg_core_reset, cfg_core_reset_wr, cfg_clk_en,
    cfg_clk_en_wr, cfg_timer_cmp, cfg_timer_cmp_wr, cfg_timer_ctrl, cfg_timer_ctrl_wr, cfg_timer_status,
    cfg_timer_status_wr, input sts_reset_cause, sts_boot_status, sts_cycles, sts_soc_id, sts_clk_status,
    sts_timer_status);
  modport core (output sts_reset_cause, sts_boot_status, sts_cycles, sts_soc_id, sts_clk_status,
    sts_timer_status, input cfg_reset_cause, cfg_reset_cause_wr, cfg_core_reset, cfg_core_reset_wr,
    cfg_clk_en, cfg_clk_en_wr, cfg_timer_cmp, cfg_timer_cmp_wr, cfg_timer_ctrl, cfg_timer_ctrl_wr,
    cfg_timer_status, cfg_timer_status_wr);
  modport monitor (input cfg_reset_cause, cfg_reset_cause_wr, cfg_core_reset, cfg_core_reset_wr, cfg_clk_en,
    cfg_clk_en_wr, cfg_timer_cmp, cfg_timer_cmp_wr, cfg_timer_ctrl, cfg_timer_ctrl_wr, cfg_timer_status,
    cfg_timer_status_wr, sts_reset_cause, sts_boot_status, sts_cycles, sts_soc_id, sts_clk_status,
    sts_timer_status);
endinterface
